def summarize(rows):
    totals = {}
    for row in rows:
        if row["status"] != "settled":
            continue

        sign, digits, exponent = row["amount"].as_tuple()
        cents = 0
        for digit in digits:
            cents = cents * 10 + digit
        cents *= 10 ** (exponent + 2)
        if sign:
            cents = -cents

        team = row["team"]
        totals[team] = totals.get(team, 0) + cents

    result = {}
    for team, cents in totals.items():
        whole, fraction = divmod(abs(cents), 100)
        prefix = "-" if cents < 0 else ""
        result[team] = f"{prefix}{whole}.{fraction:02d}"
    return result

